describe('File Upload Error Handling', () => {
    const maxFileSize = 2 * 1024 * 1024; // 2 MB
    const validFilePath = 'cypress/fixtures/valid-file.txt'; // A valid file under 2MB
    const oversizedFilePath = 'cypress/fixtures/oversized-file.txt'; // A file over 2MB

    beforeEach(() => {
        cy.visit('/upload'); // Replace with the actual upload page URL
    });

    it('should upload a valid file and not show an error', () => {
        cy.get('input[type="file"]').attachFile(validFilePath);
        cy.get('button[type="submit"]').click();
        cy.get('.error-message').should('not.exist');
        cy.get('.success-message').should('be.visible').and('contain', 'File uploaded successfully');
    });

    it('should show an error when the file exceeds the maximum size limit', () => {
        cy.get('input[type="file"]').attachFile(oversizedFilePath);
        cy.get('button[type="submit"]').click();
        cy.get('.error-message').should('be.visible').and('contain', 'File size exceeds the maximum limit of 2MB');
    });
});
